{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.inventory_bin_analysis AS WITH shelfwise_inventory_cte AS ( SELECT FACILITY AS warehouse_name, \"Inventory Type\", SECTION, SHELF, CAST(quantity AS INTEGER) AS available_qty, CAST(\"Quantity Blocked\" AS INTEGER) AS blocked_qty, CAST(\"Quantity Damaged\" AS INTEGER) AS damaged_qty, CAST(\"Quantity Not Found\" AS INTEGER) AS notfound_qty, (CAST(quantity AS INTEGER) + CAST(\"Quantity Blocked\" AS INTEGER) + CAST(\"Quantity Damaged\" AS INTEGER) + CAST(\"Quantity Not Found\" AS INTEGER)) AS total_qty, CASE WHEN \"Inventory Sync\" = \'true\' AND \"Inventory Type\" LIKE \'GOOD%\' THEN CAST(quantity AS INTEGER) ELSE NULL END AS sellable_qty, CASE WHEN \"Inventory Sync\" = \'false\' THEN total_qty WHEN \"Inventory Type\" like \'%BAD%\' THEN total_qty WHEN \"Inventory Sync\" = \'true\' OR \"Inventory Type\" LIKE \'BAD%\' THEN (CAST(\"Quantity Blocked\" AS INTEGER) + CAST(\"Quantity Damaged\" AS INTEGER) + CAST(\"Quantity Not Found\" AS INTEGER)) ELSE NULL END AS non_sellable_qty, \"Item Type SKU Code\" FROM snitch_db.maplemonk.uc_new_get_shelfwise_inventory WHERE FACILITY IN (\'SAPL_EMIZA\', \'SAPL-WH2\', \'SAPL-WH1\') ), shelf as ( select enabled, zone, \"Shelf Code\", \"Sku Mixing\" AS bin_mixing, \"Section Code\", \"Shelf on Hold\" AS bin_onhold, \"Inventory Sync\" AS bin_sync, \"Warehouse Name\" AS facility, \"Shelf Type Code\", \"Shelf Status Code\", \"Inventory Allocation\" AS bin_allocation from snitch_db.maplemonk.uc_new_get_shelf_report ) SELECT a.*, b.warehouse_name, b.\"Inventory Type\", b.available_qty, b.blocked_qty, b.damaged_qty, b.notfound_qty, b.total_qty, b.\"Item Type SKU Code\" as sku, b.sellable_qty, b.non_sellable_qty, c.sku_group, c.\"SKU_CLASS\", c.category_code AS sku_category, CASE WHEN LEFT(a.\"Shelf Code\", 1) = \'F\' THEN \'NEW_BIN\' ELSE \'OLD_BIN\' END AS bin_category, REGEXP_SUBSTR(SPLIT_PART(a.\"Shelf Code\", \'-\', 1), \'[A-Z]+$\') AS ROW_name, SPLIT_PART(a.\"Shelf Code\", \'-\', 2) AS RACK_name, SPLIT_PART(a.\"Shelf Code\", \'-\', 3) AS SHELF_name, SPLIT_PART(a.\"Shelf Code\", \'-\', 4) AS BIN_name FROM shelf AS a LEFT JOIN shelfwise_inventory_cte AS b ON CONCAT(a.facility,a.\"Shelf Code\") = CONCAT(b.warehouse_name,b.SHELF) LEFT JOIN snitch_db.maplemonk.uc_final_item_master AS c ON UPPER(TRIM(\"Item Type SKU Code\")) = UPPER(TRIM(c.sku)) WHERE FACILITY IN (\'SAPL_EMIZA\', \'SAPL-WH2\', \'SAPL-WH1\') ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LOW_QTY_BINS AS with data as ( select facility, \"Shelf Code\" as SHELF_CODE, zone, \"Section Code\" as SECTION_CODE, BIN_CATEGORY,ROW_NAME,RACK_NAME,SHELF_NAME,BIN_NAME, sum(total_qty) as TOTAL_QTY from snitch_db.maplemonk.inventory_bin_analysis where \"Section Code\" not in (\'DEF\') AND lower(\"Shelf Code\") not like \'%half%\' AND (\"Shelf Code\") not like \'%R1-%\' AND (\"Shelf Code\") not like \'%R2-%\' AND (\"Shelf Code\") not like \'%R3-%\' AND (\"Shelf Code\") not like \'%R4%\' AND (\"Shelf Code\") not like \'%R5%\' AND (\"Shelf Code\") not like \'%R6%\' AND (\"Shelf Code\") not like \'%R7%\' AND (\"Shelf Code\") not like \'%R8%\'AND (\"Shelf Code\") not like \'%R9%\' group by 1,2,3,4,5,6,7,8,9 ), analysis as ( select *, CASE WHEN TOTAL_QTY is null or total_qty = 0 then \'0\' WHEN TOTAL_QTY = 1 then \'1\' WHEN TOTAL_QTY = 2 then \'2\' WHEN TOTAL_QTY = 3 then \'3\' WHEN TOTAL_QTY = 4 then \'4\' WHEN TOTAL_QTY = 5 then \'5\' WHEN TOTAL_QTY >= 6 and TOTAL_QTY < 11 then \'6-10\' WHEN TOTAL_QTY >= 11 and TOTAL_QTY <= 15 then \'11-15\' WHEN TOTAL_QTY >= 16 and TOTAL_QTY <= 20 then \'16-20\' WHEN TOTAL_QTY >= 21 and TOTAL_QTY <= 25 then \'21-25\' WHEN TOTAL_QTY >= 26 and TOTAL_QTY <= 50 then \'26-50\' WHEN TOTAL_QTY >= 51 then \'51+\' ELSE NULL END AS BRACKET from data ) SELECT * FROM analysis ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            